  ('tpl_lead_promo_sms', 'lead_promo_sms', '{"uz":"Forest: birinchi buyurtmaga −10% promokod {kod}. 7 kun amal qiladi. {link}","ru":"Forest: промокод −10% на первый заказ {kod}. Действует 7 дней. {link}"}'::jsonb, NULL, 0, true, true, CURRENT_TIMESTAMP),
