  ('tpl_order_delivered', 'order_delivered', '{"uz":"Yetkazildi. Bo''yashdan oldin 4 daqiqalik qo''llanmani ko''ring: natija ancha yaxshi chiqadi.","ru":"Доставлено. Перед покраской посмотрите 4-минутную инструкцию — результат будет заметно лучше."}'::jsonb, '[{"text":{"uz":"Video qo''llanma ↗","ru":"Видеоинструкция ↗"},"url":"{link}"}]'::jsonb, 0, true, true, CURRENT_TIMESTAMP),
  ('tpl_payment_reminder', 'payment_reminder', '{"uz":"Forest: buyurtma {raqam} to''lovi yakunlanmadi. Mahsulot yana {vaqt} band turadi. To''lash: {link}","ru":"Forest: оплата заказа {raqam} не завершена. Товар зарезервирован ещё на {vaqt}. Оплатить: {link}"}'::jsonb, '[{"text":{"uz":"To''lash ↗","ru":"Оплатить ↗"},"url":"{link}"}]'::jsonb, 0, true, true, CURRENT_TIMESTAMP),
